import re

p = 'rev_flecksofgold/flecks'
with open(p, 'rb') as f:
    data = f.read()

# 1) Find PREFIX{...} ASCII tokens
brace_tokens = set()
for m in re.finditer(rb'([A-Za-z_][A-Za-z0-9_]{2,})\{([^}\r\n]{1,100})\}', data):
    try:
        brace_tokens.add(m.group(0).decode('ascii'))
    except Exception:
        pass

print('BRACE_TOKENS_COUNT:', len(brace_tokens))
for s in sorted(brace_tokens):
    print('BRACE:', s)

# 2) Locate anchor and extract subsequent NUL-terminated ASCII names
anchor = b' has found a flag part'
i = data.find(anchor)
print('ANCHOR_OFFSET:', i)
if i != -1:
    j = i + len(anchor)
    # Find "flecs.h\\0" nearby, then start after it
    k = data.find(b'flecs.h\x00', j)
    start = (k + len(b'flecs.h\x00')) if k != -1 else (j + 1)
    names = []
    pos = start
    while pos < len(data):
        end = data.find(b'\x00', pos, pos + 128)
        if end == -1:
            break
        s = data[pos:end]
        pos = end + 1
        if not s:
            continue
        try:
            t = s.decode('ascii')
        except Exception:
            break
        if t == '::':
            break
        if not (1 <= len(t) <= 40):
            break
        if any(ord(ch) < 32 or ord(ch) > 126 for ch in t):
            break
        names.append(t)
        if len(names) > 500:
            break
    print('NAMES_COUNT:', len(names))
    for n in names:
        print('NAME:', n)
